// Responsive image sources generated by `npm run images`.
const modules = import.meta.glob<string>('../assets/images/*.webp', {
  eager: true,
  import: 'default',
});

export interface ResponsiveImage {
  src: string;
  srcSet: string;
}

export function image(name: string): ResponsiveImage {
  const small = modules[`../assets/images/${name}-640.webp`];
  const large = modules[`../assets/images/${name}-1024.webp`];
  if (!small || !large) throw new Error(`Missing image: ${name}`);
  return { src: large, srcSet: `${small} 640w, ${large} 1024w` };
}
